from typing import Any


def evaluate(results: list[dict[str, Any]]) -> dict[str, float]:
    """results: 每条任务的三项验收结果（摘要口径：完成/准确/是否需人工介入）。"""
    n = len(results)
    if n == 0:
        return {"SR": float("nan"), "HIR": float("nan")}
    sr = sum(1 for r in results if r["completed"] and r["accurate"]) / n
    hir = sum(1 for r in results if r["human_intervention"]) / n
    return {"SR": sr, "HIR": hir}


tasks = [
    {"completed": True, "accurate": True, "human_intervention": False},
    {"completed": True, "accurate": False, "human_intervention": True},
    {"completed": True, "accurate": True, "human_intervention": True},
]
print(evaluate(tasks))  # {'SR': 0.6666666666666666, 'HIR': 0.6666666666666666}

def drain_seconds(backlog, rate, arrival):
    """backlog: 当前 LAG 总量; rate: 消费速率 msg/s; arrival: 到达速率 msg/s."""
    if rate <= arrival:
        return None  # 永远排不空，必须先扩容或限流
    return backlog / (rate - arrival)

# 例：LAG 120 万，消费 8000/s，到达 5000/s -> 400 秒排空
print(drain_seconds(1_200_000, 8000, 5000))

def parallelism(consumers, partitions):
    return min(consumers, partitions)


def partition_skew(lags):
    """lags: 每个分区的当前 LAG 列表."""
    if not lags or sum(lags) == 0:
        return 0.0
    mean = sum(lags) / len(lags)
    return max(lags) / mean if mean else 0.0

lags = [9000, 120, 150, 8000, 130]
print(parallelism(8, 5), partition_skew(lags))  # 5, 4.17 -> 有热分区

import torch


def wush_transforms(X, W, eps=1e-5):
    """示意：分别用两个因子的二阶统计做白化，成对施加以保持乘积不变。"""
    def whiten(S):
        d, V = torch.linalg.eigh(S + eps * torch.eye(S.shape[0], device=S.device))
        return V @ torch.diag(d.rsqrt()) @ V.t()

    Sx = X.t() @ X / max(X.shape[0] - 1, 1)      # [d_in, d_in]
    Sw = W @ W.t() / max(W.shape[1] - 1, 1)      # [d_out, d_out]
    Tx, Tw = whiten(Sx), whiten(Sw)
    # X @ W == (Tx @ X) @ (Tw.inverse() @ W)  -> 成对量化后再还原
    return Tx, torch.linalg.inv(Tw)
